        s._local_credential_status_history_cursors, s._did_history_cursors,
        s._did_deactivation_event_cursors, s._trust_anchor_change_cursors,
    )

def diff(a, b, path=""):
    out = []
    if type(a) != type(b):
        return [f"{path}: type {type(a).__name__} != {type(b).__name__} ({a!r} vs {b!r})"]
    if isinstance(a, dict):
        for k in set(a) | set(b):
            if k not in a: out.append(f"{path}: key {k!r} only in reloaded")
            elif k not in b: out.append(f"{path}: key {k!r} only in live")
            else: out += diff(a[k], b[k], f"{path}.{k!r}")
    elif isinstance(a, (list, tuple)):
        if len(a) != len(b): out.append(f"{path}: len {len(a)} != {len(b)}")
        for i, (x, y) in enumerate(zip(a, b)):
            out += diff(x, y, f"{path}[{i}]")
    elif a != b:
        out.append(f"{path}: {a!r} != {b!r}")
    return out

